session_start(); header('Link: <logo/logo-transparent.png>; rel="icon"'); require_once('check-login.php'); require_once('student-permission-utils.php'); require_once('house-master-utils.php'); student_permission_ensure_table($con); if(!(isset($_SESSION['ACCESSLEVEL'],$_SESSION['SYSTEMTYPE'])&&$_SESSION['ACCESSLEVEL']==='user'&&$_SESSION['SYSTEMTYPE']==='Student')){header('location:index.php');exit();} if(empty($_SESSION['student_permission_csrf'])){$_SESSION['student_permission_csrf']=bin2hex(random_bytes(32));}$msg='';$teacher=student_permission_teacher($con,$_SESSION['USERID']);
if($_SERVER['REQUEST_METHOD']==='POST'&&hash_equals($_SESSION['student_permission_csrf'],$_POST['csrf']??'')){ $type=trim($_POST['permission_type']??'');$reason=trim($_POST['reason']??'');$start=str_replace('T',' ',$_POST['start_datetime']??'');$end=str_replace('T',' ',$_POST['end_datetime']??''); if($teacher===''||$type===''||$reason===''||strtotime($end)<=strtotime($start)){$msg='Complete the form correctly. A class teacher must be assigned before you can submit.';}else{$st=mysqli_prepare($con,'INSERT INTO tblstudentpermissionrequest(student_id,teacher_id,permission_type,reason,start_datetime,end_datetime) VALUES(?,?,?,?,?,?)');$u=$_SESSION['USERID'];mysqli_stmt_bind_param($st,'ssssss',$u,$teacher,$type,$reason,$start,$end);$ok=mysqli_stmt_execute($st);mysqli_stmt_close($st); if($ok){$p=@mysqli_query($con,"SELECT mobile FROM tblsystemuser WHERE userid='".mysqli_real_escape_string($con,$teacher)."' LIMIT 1");$r=$p?mysqli_fetch_assoc($p):null;$sms='New student permission request from '.$u.'. '.$type.'. Please review.';$code='';$sent=$r&&!empty($r['mobile'])&&send_bulk_sms_message($r['mobile'],$sms,$code);$msg='Request sent to your class teacher.'.($sent?' SMS notification sent.':'');}else{$msg='Could not submit request.';}}}
