?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Permission Request</title><style>body{font:16px Arial;background:#f3f6f8;margin:0}.wrap{max-width:780px;margin:35px auto;padding:20px}.card{background:#fff;padding:24px;border-radius:10px;margin-bottom:18px}input,select,textarea{box-sizing:border-box;width:100%;padding:10px;margin:6px 0 15px}textarea{height:100px}button,a{padding:11px 15px;background:#0f4c75;color:#fff;border:0;border-radius:6px;text-decoration:none}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:left}</style></head><body><main class="wrap"><a href="student-page.php">← Dashboard</a><section class="card"><h1>Request Permission</h1><p><?php echo $teacher!==''?'Your request will be sent to your class teacher.':'No class teacher is assigned yet.'; ?></p><p><?php echo student_permission_escape($msg); ?></p><form method="post"><input type="hidden" name="csrf" value="<?php echo student_permission_escape($_SESSION['student_permission_csrf']); ?>"><label>Type</label><select name="permission_type"><option>Absence from school</option><option>Medical permission</option><option>Late arrival</option><option>Other permission</option></select><label>From</label><input type="datetime-local" name="start_datetime" required><label>To</label><input type="datetime-local" name="end_datetime" required><label>Reason</label><textarea name="reason" required></textarea><button>Submit request</button></form></section><section class="card"><h2>My requests</h2><table><tr><th>Date</th><th>Type</th><th>Status</th></tr><?php if($history)while($x=mysqli_fetch_assoc($history)){?><tr><td><?php echo student_permission_escape($x['created_at']);?></td><td><?php echo student_permission_escape($x['permission_type']);?></td><td><?php echo student_permission_escape($x['status']);?></td></tr><?php }?></table></section></main></body></html>
